-- charstartoutfit: 16 inserts, 0 updates, 0 deletes

-- New entries
DELETE FROM `charstartoutfit` WHERE `race` = @Worgen; -- Worgoblin Worgen: 530–548
SET @CharStartOutfitID = (SELECT COALESCE(MAX(id), 0) FROM `charstartoutfit`);
-- ARAC

-- @Worgen classes without a Cataclysm outfit (ARAC): the outfits of @Human (Gilneans are human),
-- then @Dwarf, @NightElf, @Gnome, @Draenei
SET @CharStartOutfitID = (SELECT COALESCE(MAX(id), 0) FROM `charstartoutfit`);
SELECT @CharStartOutfitID := @CharStartOutfitID +1, @Worgen, `o`.`class`, `o`.`gender`, `o`.`outfit_id`, `o`.`item_1`, `o`.`item_2`, `o`.`item_3`, `o`.`item_4`, `o`.`item_5`, `o`.`item_6`, `o`.`item_7`, `o`.`item_8`, `o`.`item_9`, `o`.`item_10`, `o`.`item_11`, `o`.`item_12`, `o`.`item_13`, `o`.`item_14`, `o`.`item_15`, `o`.`item_16`, `o`.`item_17`, `o`.`item_18`, `o`.`item_19`, `o`.`item_20`, `o`.`item_21`, `o`.`item_22`, `o`.`item_23`, `o`.`item_24`, `o`.`display_item_1`, `o`.`display_item_2`, `o`.`display_item_3`, `o`.`display_item_4`, `o`.`display_item_5`, `o`.`display_item_6`, `o`.`display_item_7`, `o`.`display_item_8`, `o`.`display_item_9`, `o`.`display_item_10`, `o`.`display_item_11`, `o`.`display_item_12`, `o`.`display_item_13`, `o`.`display_item_14`, `o`.`display_item_15`, `o`.`display_item_16`, `o`.`display_item_17`, `o`.`display_item_18`, `o`.`display_item_19`, `o`.`display_item_20`, `o`.`display_item_21`, `o`.`display_item_22`, `o`.`display_item_23`, `o`.`display_item_24`, `o`.`inventory_type_1`, `o`.`inventory_type_2`, `o`.`inventory_type_3`, `o`.`inventory_type_4`, `o`.`inventory_type_5`, `o`.`inventory_type_6`, `o`.`inventory_type_7`, `o`.`inventory_type_8`, `o`.`inventory_type_9`, `o`.`inventory_type_10`, `o`.`inventory_type_11`, `o`.`inventory_type_12`, `o`.`inventory_type_13`, `o`.`inventory_type_14`, `o`.`inventory_type_15`, `o`.`inventory_type_16`, `o`.`inventory_type_17`, `o`.`inventory_type_18`, `o`.`inventory_type_19`, `o`.`inventory_type_20`, `o`.`inventory_type_21`, `o`.`inventory_type_22`, `o`.`inventory_type_23`, `o`.`inventory_type_24`
FROM (SELECT * FROM `charstartoutfit` WHERE FIELD(`race`, @Human, @Dwarf, @NightElf, @Gnome, @Draenei) > 0) AS `o`
JOIN (SELECT `class`, `gender`, MIN(FIELD(`race`, @Human, @Dwarf, @NightElf, @Gnome, @Draenei)) AS `pick` FROM `charstartoutfit`
      WHERE FIELD(`race`, @Human, @Dwarf, @NightElf, @Gnome, @Draenei) > 0 GROUP BY `class`, `gender`) AS `best`
  ON `best`.`class` = `o`.`class` AND `best`.`gender` = `o`.`gender` AND FIELD(`o`.`race`, @Human, @Dwarf, @NightElf, @Gnome, @Draenei) = `best`.`pick`
LEFT JOIN (SELECT DISTINCT `class` FROM `charstartoutfit` WHERE `race` = @Worgen) AS `has` ON `has`.`class` = `o`.`class`
WHERE `has`.`class` IS NULL
ORDER BY `o`.`class`, `o`.`gender`;
